# Authored quality pass; executed before first freeze, never a review approval.
def getq(n):return next(q for q in QUESTIONS if q['id']==f'{BATCH}-Q-{n:03d}')
def choices(n,changes):
 q=getq(n)
 for index,text,explanation in changes:
  oid=f'o{index+1}'
  next(o for o in q['options'] if o['id']==oid)['text']=text
  q['solution']['optionExplanations'][oid]=explanation
