# Replace the audit-process question with a genuine source-bound action distinction.
q=getq(35)
q['stem']='During navigate_to_pose, the server reports the robot’s remaining distance several times and later reports that the goal has completed. Which interpretation matches the action components?'
q['conceptIds']=[BATCH+'-C-action']
q['type']='application';q['cognitiveSkill']='application';q['assumptions']=[]
choices(35,[(0,'Remaining-distance reports are feedback; the completion report is the terminal result','The action diagram separates intermediate progress from the eventual result.'),(1,'Each remaining-distance report is necessarily a terminal result that ends the action','Intermediate feedback does not itself mean the goal has ended.'),(2,'The completion report must be a new goal request from the server to the client','The server is reporting the outcome of the existing goal, not issuing a new client goal.'),(3,'The first feedback report proves every later cancellation request will be accepted','Receiving progress does not establish unconditional cancellation acceptance.')])
q['solution'].update({'justification':'Feedback describes progress during the action; the terminal result describes the completed goal’s outcome. These have different lifecycle roles.','simpleExplanation':'Progress is not completion.','misconceptions':['Do not treat every progress update as the final result.'],'examTraps':['Do not treat every progress update as the final result.']})
choices(36,[(1,'Accepting the update is sufficient even if the computation continues using an old cached value','A supported update must actually be consumed by the active logic to alter its behavior.'),(2,'Every parameter must be immutable after node construction, even when the node supports runtime updates','The slide explicitly presents supported runtime adjustment.'),(3,'Changing the parameter is equivalent to sending a new image frame to every subscriber','Configuration changes and stream data have different semantics.')])
choices(37,[(1,'Read a parameter name and infer that this automatically declared the shown default earlier','A later read is not evidence of a prior default declaration; the code explicitly declares it.'),(3,'Treat the service name add as the current value of parameter speed','The service name and the parameter value are separate code objects.')])
choices(40,[(3,'Reading speed is equivalent to extracting the completed AddTwoInts result from future','The code reads a parameter object, not the service future.')])
