choices(43,[(1,'The high-level CNN inference callback, because inference completion defines every PWM edge','The lecture separates high-level inference from precise low-level timing.'),(2,'The ROS image-message serialization routine','Image representation is not the microcontroller’s motor-timing role.'),(3,'The RViz visualization render loop','Rendering the scene is not assigned actuator-timing responsibility.')])
